"""X-PAR-11 oxygen species ledger (AQS-PAR-004). The mass ledger closes (AQS-PAR-003); this checks the O2 species. Every O2 sink on the graph
is converted at its stoichiometry; every O2 regeneration path is listed. Combustion oxidant demand is computed for the units that draw
'combustion air' from HDR_N2, which carries N2 product (composition N2 0.99), so on the graph they burn in nitrogen.
Stoichiometry: H2 + 1/2 O2 -> H2O (7.94 kg O2/kg H2); C7.5H17 alkane cut + 11.75 O2 (3.51 kg/kg) [TURNS2012 ch. 2]; CO + 1/2 O2 (0.571);
CH2O organics + O2 (1.066); photosynthesis CO2 + H2O -> CH2O + O2 (S87, TAIZ2015). Writes docs-authority/GAS_SPECIES.md.
Run: python3 -m flow_graph.param.gas_species"""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
def ledger(g):
    E = {e['stream_id']: e for e in g['edges']}; v = lambda k: float(E[k]['rate']['value'] or 0) if k in E else 0.0
    draws = [(e['stream_id'], e['to_unit_id'], float(e['rate']['value'] or 0)) for e in g['edges'] if e['from_unit_id'] == 'HDR_O2' and e['presence'] == 'present' and float(e['rate']['value'] or 0) > 0]
    fate = {'S50': 'fuel cell: O2 + 2 H2 -> 2 H2O (water to VCD on S52)', 'S02': 'crew respiration: to CO2 (S90, RQ 0.87) and metabolic water',
            'IA-FC-AIR': 'methanol cell: to CO2 + H2O', 'IA-O2-NIT': 'nitric acid: O into HNO3', 'IA-AC-O2': 'acetic acid oxidation', 'IA-GLX-O2': 'glyoxal oxidation',
            'IA-FORM-O2': 'formaldehyde oxidation', 'IA-H2O2-SRC': 'peroxide (returns as H2O + 1/2 O2 on decomposition at the bench)'}
    comb = [('BACKUP_GEN', 'S45 H2', v('S45'), 7.94), ('BACKUP_GEN', 'CUT-1-OUT C5-C10 fuel', v('CUT-1-OUT'), 3.51), ('AFTERBURNER', 'IA-SIC-CO carbon monoxide', v('IA-SIC-CO'), 0.571),
            ('AFTERBURNER', 'S11 grow-bed organics (CH2O basis)', v('S11'), 1.066)]
    san = 0.32   # AQS-DUTY-063 Rev B combustion O2 for cake + biogas (taken on S02 there)
    ncg = v('NCG_TO_AB')
    regen = [('S87', 'grow-bed photosynthesis', v('S87'))]
    sink = sum(d for _, _, d in draws); need = sum(m*f for _, _, m, f in comb)
    if 'IA-GEN-O2' in E:     # X-PAR-12: combustion O2 is on the graph (in draws); real sources only
        need = 0.0; regen += [('IA-ASU-O2', 'cold box: excess combustion O2 recovered (species-conserving)', v('IA-ASU-O2')), ('IA-ELY-O2', 'PEM electrolyser', v('IA-ELY-O2'))]
        sink -= v('IA-O2-PROD'); draws = [x for x in draws if x[0] != 'IA-O2-PROD']; fate.update({'IA-GEN-O2': 'genset combustion, 10 % excess', 'IA-AB-O2': 'afterburner combustion, 10 % excess'})
    return dict(draws=draws, fate=fate, comb=comb, ncg=ncg, san=san, regen=regen, sink=sink, need=need, src=sum(r for _, _, r in regen), air=v('IA-AB-AIR') + v('IA-GEN-AIR'))
def write(L_):
    d = L_; deficit = d['sink'] + d['need'] - d['src']
    L = ['# Oxygen species ledger', '', 'Document number: AQS-PAR-004', 'Revision: B', 'Date: 2026-10-15',
         'Authority: AQS-PLAN-007 X-PAR-11. Generated by `flow_graph/param/gas_species.py`. A-M-129.', '', '| Rev | Description | Date |', '| --- | --- | --- |', '| A | First issue. | 2026-10-15 |', '| B | X-PAR-12: combustion O2 on the graph, electrolyser and species-conserving cold box; gap closed. | 2026-10-15 |', '',
         'The total-mass ledger closes (AQS-PAR-003). The O2 species does not: the cold box delivers O2 that no unit on the graph regenerates, and the combustion units draw their "air" from the nitrogen header.', '',
         '## 1. O2 drawn from HDR_O2 and its fate', '', '| Edge | To | kg/d | Fate |', '| --- | --- | --- | --- |'] + [f"| {k} | {t} | {r:.3f} | {d['fate'].get(k, '-')} |" for k, t, r in d['draws']] + [
         f"| total | | {d['sink']:.3f} | |", '', '## 2. Combustion oxidant not on the graph (units fed from HDR_N2)', '', '| Unit | Fuel | Fuel kg/d | kg O2/kg | O2 kg/d |', '| --- | --- | --- | --- | --- |'] + [
         f'| {u} | {f} | {m:.3f} | {k} | {m*k:.2f} |' for u, f, m, k in d['comb']] + [
         f"| total | | | | {d['need']:.2f} |", '', f"Not counted: NCG_TO_AB {d['ncg']:.2f} kg/d (composition not on the graph); sanitation cake and biogas {d['san']:.2f} kg/d O2, already taken on S02 (AQS-DUTY-063 Rev B).",
         f"The {d['air']:.1f} kg/d drawn as combustion air (IA-AB-AIR, IA-GEN-AIR) is N2 product; at 23.2 wt% O2 synthetic air it would carry {0.232*d['air']:.1f} kg/d O2.", '',
         '## 3. O2 regeneration on the graph', '', '| Edge | Path | kg/d |', '| --- | --- | --- |'] + [f'| {k} | {p} | {r:.3f} |' for k, p, r in d['regen']] + [
         '', '## 4. Result', ''] + ([f"O2 drawn {d['sink']:.2f} (combustion included, on HDR_O2) against real sources {d['src']:.2f}: no species gap; surplus {d['src'] - d['sink']:.2f} kg/d O2 to PROD_O2 (X-PAR-12, AQS-PAR-005 Rev B)."]
         if 'IA-ASU-O2' in [r[0] for r in d['regen']] else [f"O2 consumed {d['sink']:.2f} + combustion oxidant {d['need']:.2f} - regenerated {d['src']:.2f} = **{deficit:.1f} kg/d O2 with no source**."])
    open(os.path.join(ROOT, 'docs-authority/GAS_SPECIES.md'), 'w').write('\n'.join(L) + '\n'); return deficit
if __name__ == '__main__':
    g = json.load(open(os.path.join(ROOT, 'flow_graph/plant_flow_graph.json'))); d = ledger(g); print('sink', round(d['sink'], 2), 'comb', round(d['need'], 2), 'regen', round(d['src'], 2), 'deficit', round(write(d), 2))
